"""Prediccion exacta para dos paredes y una particula interior.

Entre choques la particula se traslada un sitio por paso. Cada viaje
completo conserva la pared izquierda y desplaza la derecha un sitio.
Los tiempos de esos viajes forman una progresion aritmetica, que se
invierte con una raiz cuadrada entera.
"""
from math import isqrt


def _from_left(left, right, steps):
    """Estado inicial: d en left/right y a en left+1."""
    width = right - left
    # k viajes tardan k * (k + 2*width - 3) pasos.
    base = 2 * width - 3
    k = (isqrt(base * base + 4 * steps) - base) // 2
    steps -= k * (k + base)
    right += k
    width += k

    if steps < width - 1:
        return {left: 'd', right: 'd',
                left + 1 + steps: 'ab'[steps & 1]}
    if steps == width - 1:
        return {left: 'd', right: 'e', right - 1: 'c'}
    return {left: 'd', right + 1: 'd',
            left + 2 * width - 2 - steps: 'c'}


def predict(start, steps):
    if steps == 0:
        return dict(start)
    left, right = sorted(p for p, s in start.items() if s == 'd')
    pos, symbol = next((p, s) for p, s in start.items() if s in 'abc')
    steps = int(steps)
    left, right, pos = int(left), int(right), int(pos)
    width = right - left

    if symbol == 'c':
        # Una c inicialmente pegada a la pared derecha la elimina.
        lost_right = pos == right - 1
        until_left = pos - left
        if steps < until_left:
            result = {left: 'd', pos - steps: 'c'}
            if not lost_right:
                result[right] = 'd'
            return result
        steps -= until_left
        if lost_right:
            return {left: 'd', left + 1 + steps: 'ab'[steps & 1]}
        return _from_left(left, right, steps)

    # Una b inicialmente pegada a la pared izquierda la elimina.
    lost_left = symbol == 'b' and pos == left + 1
    until_right = right - pos
    if steps < until_right:
        result = {right: 'd',
                  pos + steps: 'ab'[(int(symbol == 'b') + steps) & 1]}
    elif steps == until_right:
        result = {right: 'e', right - 1: 'c'}
    else:
        until_left = until_right + width - 1
        if not lost_left and steps >= until_left:
            return _from_left(left, right + 1, steps - until_left)
        result = {right + 1: 'd',
                  right - 1 - (steps - until_right): 'c'}
    if not lost_left:
        result[left] = 'd'
    return result

